code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            minr=min(y for y,x in cells); maxr=max(y for y,x in cells)
            minc=min(x for y,x in cells); maxc=max(x for y,x in cells)
            local={(y-minr,x-minc) for y,x in cells}
            bh, bw=maxr-minr+1, maxc-minc+1
            border={(y,x) for y in range(bh) for x in range(bw) if y in (0,bh-1) or x in (0,bw-1)}
            frame = bh >= 3 and bw >= 3 and border <= local and len(local) < bh*bw
            objects.append({'color':color,'cells':cells,'shape':local,'top':minr,'left':minc,'h':bh,'w':bw,'up':frame})
    out=[[0]*w for _ in range(h)]
    placed=[]
    # Frames pack upward in their original top-to-bottom order.
    for obj in sorted((o for o in objects if o['up']), key=lambda o:(o['top'],o['left'])):
        max_top=obj['top']
        for top in range(max_top+1):
            coords=[(top+y,obj['left']+x) for y,x in obj['shape']]
            if all(0 <= y < h and 0 <= x < w and out[y][x] == 0 for y,x in coords):
                chosen=top; break
        else:
            chosen=obj['top']
        for y,x in obj['shape']:
            out[chosen+y][obj['left']+x]=obj['color']
    # Other shapes pack downward, starting with the lowest input objects.
    for obj in sorted((o for o in objects if not o['up']), key=lambda o:(-(o['top']+o['h']),-o['left'])):
        min_top=obj['top']; max_top=h-obj['h']
        for top in range(max_top,min_top-1,-1):
            coords=[(top+y,obj['left']+x) for y,x in obj['shape']]
            if all(0 <= y < h and 0 <= x < w and out[y][x] == 0 for y,x in coords):
                chosen=top; break
        else:
            chosen=max(min_top,min(max_top,obj['top']))
        for y,x in obj['shape']:
            out[chosen+y][obj['left']+x]=obj['color']
    return out
